SELECT int16 = int32 AS c0, toTypeName(int16 = int32) AS t0, int16 != int32 AS c1, toTypeName(int16 != int32) AS t1, int16 < int32 AS c2, toTypeName(int16 < int32) AS t2, int16 <= int32 AS c3, toTypeName(int16 <= int32) AS t3, int16 > int32 AS c4, toTypeName(int16 > int32) AS t4, int16 >= int32 AS c5, toTypeName(int16 >= int32) AS t5 FROM he24.numeric ORDER BY row_id
